      for (int i = r0; i < r1; i++, w += 128) { const v128_t s = wasm_v128_load32_splat(sn_hin + i); c0 = wasm_f32x4_add(c0, wasm_f32x4_mul(s, wasm_v128_load(w + 0))); c1 = wasm_f32x4_add(c1, wasm_f32x4_mul(s, wasm_v128_load(w + 4))); c2 = wasm_f32x4_add(c2, wasm_f32x4_mul(s, wasm_v128_load(w + 8))); c3 = wasm_f32x4_add(c3, wasm_f32x4_mul(s, wasm_v128_load(w + 12))); c4 = wasm_f32x4_add(c4, wasm_f32x4_mul(s, wasm_v128_load(w + 16))); c5 = wasm_f32x4_add(c5, wasm_f32x4_mul(s, wasm_v128_load(w + 20))); c6 = wasm_f32x4_add(c6, wasm_f32x4_mul(s, wasm_v128_load(w + 24))); c7 = wasm_f32x4_add(c7, wasm_f32x4_mul(s, wasm_v128_load(w + 28))); }
